 private void updateNowPlaying(){if(playButton==null)return;boolean playing=player!=null&&player.isPlaying();playButton.setImageResource(playing?R.drawable.ic_pause:R.drawable.ic_play_arrow);playButton.setContentDescription(playing?"一時停止":"再生");muteButton.setImageResource(muted?R.drawable.ic_volume_off:R.drawable.ic_volume_up);muteButton.setContentDescription(muted?"音声を出す":"消音");fitButton.setImageResource(fillVideo?R.drawable.ic_fit_screen:R.drawable.ic_crop_free);fitButton.setContentDescription(fillVideo?"映像全体を表示":"画面いっぱいに拡大");expandButton.setImageResource(fullscreen?R.drawable.ic_fullscreen_exit:R.drawable.ic_fullscreen);expandButton.setContentDescription(fullscreen?"全画面を閉じる":"全画面で表示");expandButton.setEnabled(current!=null);exitButton.setVisibility(fullscreen?View.VISIBLE:View.GONE);controls.setVisibility(current==null?View.GONE:View.VISIBLE);nowPanel.setVisibility(current==null||fullscreen?View.GONE:View.VISIBLE);playerTop.setVisibility(current==null?View.GONE:View.VISIBLE);playerBottom.setVisibility(current==null?View.GONE:View.VISIBLE);if(current==null){currentName.setText("ライブ");playerSubtitle.setText("局を選択してください");return;}currentName.setText(current.display+"  "+current.name);nowTitle.setText(current.display+"  "+current.name);ArrayList<TsEpg.Event> events=epg.forChannel(current);String programme=events.isEmpty()?"番組情報を受信すると表示します":events.get(0).title;nowProgram.setText(programme);playerSubtitle.setText(playing?(events.isEmpty()?"ライブ放送":events.get(0).title):status.getText());String key=StationIdentity.key(current,config.channels);for(FrameLayout slot:new FrameLayout[]{playerLogoSlot,nowLogoSlot}){String tag=key+current.name;if(!tag.equals(slot.getTag())){slot.removeAllViews();slot.addView(logos.view(current,config.channels,slot==playerLogoSlot?32:40),new FrameLayout.LayoutParams(-1,-1));slot.setTag(tag);}}}
