 private void playerEvent(MediaPlayer.Event event){if(destroyed)return;if(event.type==MediaPlayer.Event.Playing){overlay.setVisibility(View.GONE);status.setText("視聴中 · チューナー"+(config==null?"":config.tuner+1));updateNowPlaying();showPlayerControls(true);video.post(this::resizeVideo);ui.postDelayed(this::resizeVideo,800);}else if(event.type==MediaPlayer.Event.EncounteredError){status.setText("再生できませんでした。局を選び直してください");overlay.setText("再生できませんでした");overlay.setVisibility(View.VISIBLE);updateNowPlaying();showPlayerControls(true);}else if(event.type==MediaPlayer.Event.Paused||event.type==MediaPlayer.Event.Stopped||event.type==MediaPlayer.Event.EndReached){updateNowPlaying();showPlayerControls(true);}}
 private void showPlayerControls(boolean show){chromeVisible=show;ui.removeCallbacks(hideChrome);if(playerChrome==null)return;playerChrome.setVisibility(show?View.VISIBLE:View.GONE);if(show){if(current!=null)overlay.setVisibility(View.GONE);updateNowPlaying();android.view.accessibility.AccessibilityManager manager=(android.view.accessibility.AccessibilityManager)getSystemService(ACCESSIBILITY_SERVICE);if(player!=null&&player.isPlaying()&&(manager==null||!manager.isTouchExplorationEnabled()))ui.postDelayed(hideChrome,3000);}}
 private void setVideoFill(boolean fill){if(fillVideo==fill){showPlayerControls(true);return;}fillVideo=fill;getPreferences(0).edit().putBoolean("fill_video",fill).apply();resizeVideo();updateNowPlaying();Toast.makeText(this,fill?"画面いっぱい":"映像全体",Toast.LENGTH_SHORT).show();showPlayerControls(true);}
